import { describe, test } from 'node:test';
import assert from 'node:assert';
import { SignalGenerator } from '../../backend/strategy/signal_generator.js';
import { RegimeType } from '../../backend/regime/detector.js';

function makeBaseRow(overrides: Record<string, any> = {}) {
  return {
    time: Date.now(),
    open: 100,
    high: 105,
    low: 99,
    close: 102,
    ema_9: 101,
    ema_21: 100,
    ema_50: 98,
    rsi_14: 58,
    bb_upper: 110,
    bb_middle: 100,
    bb_lower: 95,
    vwap: 101,
    adx: 30,
    adx_plus: 28,
    adx_minus: 18,
    stoch_rsi_k: 20,
    stoch_rsi_d: 18,
    macd_line: 1.5,
    signal_line: 1.0,
    macd_histogram: 0.5,
    volume_sma_20: 100,
    volume_ratio: 1.4,
    atr: 2.5,
    ...overrides
  };
}

function makeDf(lastOverrides: Record<string, any> = {}) {
  const filler = Array.from({ length: 60 }).map((_, i) =>
    makeBaseRow({ time: i, close: 100 + i * 0.05, rsi_14: 52, stoch_rsi_k: 45, volume_ratio: 1.1 })
  );
  filler[filler.length - 1] = makeBaseRow(lastOverrides);
  return filler;
}

describe.skip('SignalGenerator branch coverage [LEGACY-QUARANTINED]', () => {
  test('returns null for short datasets', async () => {
    const generator = new SignalGenerator();
    const result = await generator.generateSignal([makeBaseRow()], RegimeType.STRONG_BULL, 'BTC/USDT');
    assert.strictEqual(result, null);
  });

  test('generates regime strategy signals across all regimes', async () => {
    const generator = new SignalGenerator();

    const strongBull = await generator.generateSignal(makeDf(), RegimeType.STRONG_BULL, 'BTC/USDT');
    assert.ok(strongBull && strongBull.side === 'buy');

    const weakBull = await generator.generateSignal(
      makeDf({ close: 95.2, open: 95.1, bb_lower: 95, vwap: 95, rsi_14: 35, volume_ratio: 1.2 }),
      RegimeType.WEAK_BULL,
      'BTC/USDT'
    );
    assert.ok(weakBull && weakBull.side === 'buy');

    const bear = await generator.generateSignal(
      makeDf({ ema_9: 99, ema_21: 101, rsi_14: 68, high: 109.6, bb_upper: 110, close: 101, open: 104, macd_line: -1, signal_line: 0 }),
      RegimeType.BEAR,
      'BTC/USDT'
    );
    assert.ok(bear && bear.side === 'sell');

    const sideways = await generator.generateSignal(
      makeDf({ close: 95.2, bb_lower: 95, rsi_14: 30, stoch_rsi_k: 20, volume_ratio: 1.1 }),
      RegimeType.SIDEWAYS,
      'BTC/USDT'
    );
    assert.ok(sideways);
  });

  test('generates alternate strategy signals and null default for uncertain regime', async () => {
    const generator = new SignalGenerator();
    const shotgun = await generator.generateSignal(makeDf({ rsi_14: 55 }), RegimeType.UNCERTAIN, 'BTC/USDT', false, 'shotgun');
    assert.ok(shotgun && shotgun.reasoning.includes('Shotgun'));

    const alt = await generator.generateSignal(
      makeDf({ close: 110 }),
      RegimeType.UNCERTAIN,
      'BTC/USDT',
      false,
      'alt_chaser'
    );
    assert.ok(alt && ['buy', 'sell'].includes(alt.side));

    const dragons = await generator.generateSignal(makeDf({ rsi_14: 60 }), RegimeType.UNCERTAIN, 'BTC/USDT', false, 'chasing_dragons');
    assert.ok(dragons && dragons.confidence === 75);

    const uncertainDefault = await generator.generateSignal(makeDf(), RegimeType.UNCERTAIN, 'BTC/USDT');
    assert.strictEqual(uncertainDefault, null);
  });
});

import { RegimeType } from '../regime/detector.js';

export interface Signal {
  symbol: string;
  side: 'buy' | 'sell';
  confidence: number;
  entryPrice: number;
  stopLoss: number;
  takeProfit: number;
  reasoning: string;
  indicators: string[]; // List of indicators that triggered the signal
  aiWarning?: boolean; // Flag for non-critical AI errors
}

export class SignalGenerator {
  static aiEnabled = true;
  static aiHealth: {
    totalRequests: number;
    successfulConfirmations: number;
    failedConfirmations: number;
    lastFailureReason: string | null;
    circuitBreakerTripped: boolean;
    consecutiveFailures: number;
  } = {
    totalRequests: 0,
    successfulConfirmations: 0,
    failedConfirmations: 0,
    lastFailureReason: null,
    circuitBreakerTripped: false,
    consecutiveFailures: 0
  };

  private streamingBuffers: Map<string, any[]> = new Map();
  private maxBufferSize = 100;

  // ATR multipliers for different regimes (conservative to aggressive)
  private static ATR_STOP_MULTIPLIERS = {
    ultra_conservative: 2.0,
    conservative: 1.8,
    moderate: 1.5,
    aggressive: 1.2,
    degen: 1.0,
    ai_enhanced: 1.5
  };

  private static ATR_PROFIT_MULTIPLIERS = {
    ultra_conservative: 1.0,
    conservative: 1.2,
    moderate: 1.5,
    aggressive: 2.0,
    degen: 2.5,
    ai_enhanced: 1.5
  };

  static resetAIHealth() {
    this.aiHealth = {
      totalRequests: 0,
      successfulConfirmations: 0,
      failedConfirmations: 0,
      lastFailureReason: null,
      circuitBreakerTripped: false,
      consecutiveFailures: 0
    };
  }

  static getAIHealth() {
    const h = this.aiHealth;
    const successRate = h.totalRequests > 0 ? (h.successfulConfirmations / h.totalRequests) * 100 : 0;
    return {
      ...h,
      successRate,
      aiAvailable: this.aiEnabled && !this.aiHealth.circuitBreakerTripped
    };
  }

  private calculateATRAdjustedLevels(entryPrice: number, atr: number, side: 'buy' | 'sell', riskMode: string): { stopLoss: number, takeProfit: number } {
    const stopMultiplier = SignalGenerator.ATR_STOP_MULTIPLIERS[riskMode] || 1.5;
    const profitMultiplier = SignalGenerator.ATR_PROFIT_MULTIPLIERS[riskMode] || 1.5;

    if (side === 'buy') {
      const stopLoss = entryPrice - (stopMultiplier * atr);
      const takeProfit = entryPrice + (profitMultiplier * atr);
      return { stopLoss, takeProfit };
    } else {
      const stopLoss = entryPrice + (stopMultiplier * atr);
      const takeProfit = entryPrice - (profitMultiplier * atr);
      return { stopLoss, takeProfit };
    }
  }

  // Streaming signal generation
  addToStream(symbol: string, candle: any): void {
    let buffer = this.streamingBuffers.get(symbol);
    if (!buffer) {
      buffer = [];
      this.streamingBuffers.set(symbol, buffer);
    }

    buffer.push(candle);

    // Keep buffer size manageable
    if (buffer.length > this.maxBufferSize) {
      buffer.shift();
    }
  }

  async generateStreamingSignal(
    symbol: string,
    regime: RegimeType,
    useAI: boolean = false,
    strategy: string = 'regime',
    riskMode: string = 'moderate'
  ): Promise<Signal | null> {
    const buffer = this.streamingBuffers.get(symbol);
    if (!buffer || buffer.length < 50) {
      return null; // Need minimum data for indicators
    }

    // Use the most recent data
    return this.generateSignal(buffer, regime, symbol, useAI, strategy, riskMode);
  }

  getStreamingBufferSize(symbol: string): number {
    const buffer = this.streamingBuffers.get(symbol);
    return buffer ? buffer.length : 0;
  }

  clearStreamingBuffer(symbol: string): void {
    this.streamingBuffers.delete(symbol);
  }

  async generateSignal(df: any[], regime: RegimeType, symbol: string, useAI: boolean = false, strategy: string = 'regime', riskMode: string = 'moderate'): Promise<Signal | null> {
    if (df.length < 50) return null;

    let signal: Signal | null = null;

    if (strategy === 'shotgun') {
      signal = this._shotgunStrategy(df, symbol, riskMode);
    } else if (strategy === 'alt_chaser') {
      signal = this._altChaserStrategy(df, symbol, riskMode);
    } else if (strategy === 'chasing_dragons') {
      signal = this._chasingDragonsStrategy(df, symbol, riskMode);
    } else {
      switch (regime) {
        case RegimeType.STRONG_BULL:
          signal = this._strongBullStrategy(df, symbol, riskMode);
          break;
        case RegimeType.WEAK_BULL:
          signal = this._weakBullStrategy(df, symbol, riskMode);
          break;
        case RegimeType.BEAR:
          signal = this._bearStrategy(df, symbol, riskMode);
          break;
        case RegimeType.SIDEWAYS:
          signal = this._sidewaysStrategy(df, symbol, riskMode);
          break;
        default:
          return null;
      }
    }

    if (signal && useAI && SignalGenerator.aiEnabled && !SignalGenerator.aiHealth.circuitBreakerTripped) {
      try {
        const apiKey = process.env.GEMINI_API_KEY;
        if (!apiKey) {
          console.warn("AI Signal Confirmation skipped: GEMINI_API_KEY is not set.");
          SignalGenerator.aiHealth.totalRequests++;
          SignalGenerator.aiHealth.failedConfirmations++;
          SignalGenerator.aiHealth.consecutiveFailures++;
          SignalGenerator.aiHealth.lastFailureReason = 'GEMINI_API_KEY not configured';
          signal.aiWarning = true;
          // Disable AI features when no key is configured
          SignalGenerator.aiEnabled = false;
          if (SignalGenerator.aiHealth.consecutiveFailures >= 3) {
            SignalGenerator.aiHealth.circuitBreakerTripped = true;
            console.error('[AI Circuit Breaker] Tripped due to missing API key');
          }
        } else {
          const { GoogleGenAI } = await import('@google/genai');
          const ai = new GoogleGenAI({ apiKey });

          const lastCandles = df.slice(-5).map(c => ({
            time: new Date(c.time).toISOString(),
            open: c.open,
            high: c.high,
            low: c.low,
            close: c.close,
            volume: c.volume
          }));

          const prompt = `You are a quantitative trading system. A base algorithm has generated a ${signal.side.toUpperCase()} signal for ${symbol} based on ${signal.indicators.join(', ')}.
          Entry: ${signal.entryPrice}, Stop Loss: ${signal.stopLoss}, Take Profit: ${signal.takeProfit}.
          Recent price action: ${JSON.stringify(lastCandles)}

          Do you confirm this trade? If the macro structure looks poor, reject it.
          Return a JSON object:
          { "confirmed": boolean, "reasoning": "string" }`;

          const response = await ai.models.generateContent({
            model: "gemini-3-flash-preview",
            contents: prompt,
            config: {
              responseMimeType: "application/json"
            }
          });

          if (response.text) {
            const aiResult = JSON.parse(response.text);
            SignalGenerator.aiHealth.totalRequests++;
            SignalGenerator.aiHealth.successfulConfirmations++;
            SignalGenerator.aiHealth.consecutiveFailures = 0;
            if (!aiResult.confirmed) {
              console.log(`AI rejected signal for ${symbol}: ${aiResult.reasoning}`);
              return null; // Block trade when AI rejects
            } else {
              signal.reasoning = `AI Confirmed: ${aiResult.reasoning}`;
            }
          }
        }
      } catch (e: any) {
        SignalGenerator.aiHealth.totalRequests++;
        SignalGenerator.aiHealth.failedConfirmations++;
        SignalGenerator.aiHealth.consecutiveFailures++;
        SignalGenerator.aiHealth.lastFailureReason = e.message || String(e);

        if (e.message && e.message.includes("API_KEY_INVALID")) {
          console.error("AI Signal Confirmation failed: Invalid API Key. Disabling AI features.");
          SignalGenerator.aiEnabled = false;
          SignalGenerator.aiHealth.circuitBreakerTripped = true;
          return null; // Block trade when AI key is invalid and AI is required
        } else {
          console.error("AI Signal Confirmation failed:", e);
          // Non-critical AI error: add warning flag to signal, allow trade to proceed
          signal.aiWarning = true;
          signal.reasoning += ` [AI Confirmation Failed: ${e.message}]`;

          // Circuit breaker: trip after 5 consecutive failures
          if (SignalGenerator.aiHealth.consecutiveFailures >= 5) {
            SignalGenerator.aiHealth.circuitBreakerTripped = true;
            console.error(`[AI Circuit Breaker] Tripped after ${SignalGenerator.aiHealth.consecutiveFailures} consecutive failures. AI features disabled temporarily.`);
            SignalGenerator.aiEnabled = false;
          }
        }
      }
    }

    return signal;
  }

  _strongBullStrategy(df: any[], symbol: string, riskMode: string): Signal | null {
    const data = df[df.length - 1];
    let score = 0;
    const indicators: string[] = [];

    // Trend confirmation (45%)
    if (data.close > data.ema_9 && data.ema_9 > data.ema_21) {
      score += 45;
      indicators.push('EMA Trend');
    } else {
      return null; // Trend must be intact
    }

    // RSI Momentum (20%)
    if (data.rsi_14 > 50 && data.rsi_14 < 75) {
      score += 20;
      indicators.push('RSI Momentum');
    } else if (data.rsi_14 >= 75) {
      score += 5;
      indicators.push('RSI Overbought');
    }

    // Volume Confirmation (20%)
    if (data.volume_ratio > 1.2) {
      score += 20;
      indicators.push('Volume Surge');
    }

    // Timing: Stoch RSI (15%)
    if (data.stoch_rsi_k < 30) {
      score += 15;
      indicators.push('StochRSI Oversold');
    } else if (data.stoch_rsi_k < 50) {
      score += 5;
      indicators.push('StochRSI Moderate');
    }

    if (score >= 60) {
      const { stopLoss, takeProfit } = this.calculateATRAdjustedLevels(data.close, data.atr, 'buy', riskMode);
      return {
        symbol,
        side: 'buy',
        confidence: score,
        entryPrice: data.close,
        stopLoss,
        takeProfit,
        reasoning: `Strong Bull: Score ${score} - ${indicators.join(', ')} (ATR-adjusted)`,
        indicators
      };
    }
    return null;
  }

  _weakBullStrategy(df: any[], symbol: string, riskMode: string): Signal | null {
    const data = df[df.length - 1];
    let score = 0;
    const indicators: string[] = [];

    // Strategy A: Mean reversion (60% weight)
    if (data.close <= data.bb_lower * 1.01) {
      if (data.close > data.vwap * 0.995) {
        if (data.rsi_14 < 40) {
          score += 60;
          indicators.push('Mean Reversion (BB/VWAP/RSI)');
        }
      }
    }
    // Strategy B: Momentum continuation (40% weight)
    else if (data.close > data.ema_9 && data.ema_9 > data.ema_21) {
      if (data.rsi_14 > 50 && data.rsi_14 < 70) {
        if (data.volume_ratio > 1.3) {
          score += 40;
          indicators.push('Momentum Breakout');
        }
      }
    }

    // Volume confirmation boost
    if (data.close > data.open && data.volume_ratio > 1.1) {
      score += 15;
      indicators.push('Bullish Volume');
    }

    // Penalty: Wrong side of VWAP
    if (data.close < data.vwap * 0.98) {
      score *= 0.7;
    }

    if (score >= 50) {
      const { stopLoss, takeProfit } = this.calculateATRAdjustedLevels(data.close, data.atr, 'buy', riskMode);
      return {
        symbol,
        side: 'buy',
        confidence: Math.min(score, 100),
        entryPrice: data.close,
        stopLoss,
        takeProfit,
        reasoning: `Weak Bull: Score ${Math.min(score, 100).toFixed(0)} - ${indicators.join(', ')} (ATR-adjusted)`,
        indicators
      };
    }
    return null;
  }

  _bearStrategy(df: any[], symbol: string, riskMode: string): Signal | null {
    const data = df[df.length - 1];
    let score = 0;
    const indicators: string[] = [];

    // Must have: Downtrend confirmed
    if (data.ema_9 < data.ema_21) {
      score += 30;
      indicators.push('Downtrend EMA');
    } else {
      return null;
    }

    // Resistance rejection
    if (data.high >= data.bb_upper * 0.995) {
      if (data.close < data.open) {
        if (data.rsi_14 > 60) {
          score += 50;
          indicators.push('Resistance Rejection');
        }
      }
    } else if (data.rsi_14 > 65 && data.rsi_14 < 75) {
      score += 35;
      indicators.push('Failed Rally');
    }

    // MACD confirmation
    if (data.macd_line < data.signal_line) {
      score += 15;
      indicators.push('MACD Bearish');
    }

    if (score >= 50) {
      const { stopLoss, takeProfit } = this.calculateATRAdjustedLevels(data.close, data.atr, 'sell', riskMode);
      return {
        symbol,
        side: 'sell',
        confidence: score,
        entryPrice: data.close,
        stopLoss,
        takeProfit,
        reasoning: `Bear: Score ${score} - ${indicators.join(', ')} (ATR-adjusted)`,
        indicators
      };
    }
    return null;
  }

  _sidewaysStrategy(df: any[], symbol: string, riskMode: string): Signal | null {
    const data = df[df.length - 1];
    let score = 0;
    let side: 'buy' | 'sell' = 'buy';
    const indicators: string[] = [];

    // Long Setup
    if (data.close <= data.bb_lower * 1.005) {
      score += 30;
      indicators.push('BB Lower');
      if (data.rsi_14 < 35) {
        score += 25;
        indicators.push('RSI Oversold');
      }
      if (data.stoch_rsi_k < 25) {
        score += 20;
        indicators.push('Stoch Oversold');
      }
      side = 'buy';
    }
    // Short Setup
    else if (data.close >= data.bb_upper * 0.995) {
      score += 30;
      indicators.push('BB Upper');
      if (data.rsi_14 > 65) {
        score += 25;
        indicators.push('RSI Overbought');
      }
      if (data.stoch_rsi_k > 75) {
        score += 20;
        indicators.push('Stoch Overbought');
      }
      side = 'sell';
    }

    // Volume filter: Reduce if volume spiking
    if (data.volume_ratio > 1.5) {
      score *= 0.5;
      indicators.push('Volume Spike Penalty');
    }

    if (score >= 50) {
      const { stopLoss, takeProfit } = this.calculateATRAdjustedLevels(data.close, data.atr, side, riskMode);
      return {
        symbol,
        side,
        confidence: score,
        entryPrice: data.close,
        stopLoss,
        takeProfit,
        reasoning: `Sideways: Score ${score} - ${indicators.join(', ')} (ATR-adjusted)`,
        indicators
      };
    }

    return null;
  }

  _shotgunStrategy(df: any[], symbol: string, riskMode: string): Signal | null {
    // Shotgun: Buy/sell 0.5s before candle end, close 10s after.
    // This needs to be triggered at specific times.
    // For now, let's just return a signal if indicators align.
    const last = df[df.length - 1];
    if (last.rsi_14 > 50) {
      const { stopLoss, takeProfit } = this.calculateATRAdjustedLevels(last.close, last.atr, 'buy', riskMode);
      return {
        symbol,
        side: 'buy',
        confidence: 60,
        entryPrice: last.close,
        stopLoss,
        takeProfit,
        reasoning: 'Shotgun: Triggered by RSI (ATR-adjusted)',
        indicators: ['RSI']
      };
    }
    return null;
  }

  _altChaserStrategy(df: any[], symbol: string, riskMode: string): Signal | null {
    const last = df[df.length - 1];
    const prev = df[df.length - 2];
    const change = Math.abs(last.close - prev.close) / prev.close;
    if (change > 0.01) {
      const side = last.close > prev.close ? 'buy' : 'sell';
      const { stopLoss, takeProfit } = this.calculateATRAdjustedLevels(last.close, last.atr, side, riskMode);
      return {
        symbol,
        side,
        confidence: 65,
        entryPrice: last.close,
        stopLoss,
        takeProfit,
        reasoning: 'Alt Chaser: Price change > 1% (ATR-adjusted)',
        indicators: ['Price Action']
      };
    }
    return null;
  }

  _chasingDragonsStrategy(df: any[], symbol: string, riskMode: string): Signal | null {
    const last = df[df.length - 1];
    // Placeholder for probability score logic
    if (last.rsi_14 > 50) {
      const { stopLoss, takeProfit } = this.calculateATRAdjustedLevels(last.close, last.atr, 'buy', riskMode);
      return {
        symbol,
        side: 'buy',
        confidence: 75,
        entryPrice: last.close,
        stopLoss,
        takeProfit,
        reasoning: 'Chasing Dragons: Probability score maintained (ATR-adjusted)',
        indicators: ['RSI']
      };
    }
    return null;
  }
}

export enum RegimeType {
  STRONG_BULL = "strong_bull",
  WEAK_BULL = "weak_bull",
  BEAR = "bear",
  SIDEWAYS = "sideways",
  UNCERTAIN = "uncertain"
}

export class RegimeDetector {
  static aiEnabled = true;

  STRONG_BULL_THRESHOLDS = {
    adx_min: 30,
    price_30d_min: 0.12,
    price_7d_min: 0.03,
    volume_ratio_min: 1.3
  };

  BEAR_THRESHOLDS = {
    price_30d_max: -0.08,
    price_7d_max: -0.05,
    rsi_avg_max: 40
  };

  SIDEWAYS_THRESHOLDS = {
    adx_max: 20,
    price_30d_range: 0.04,
    price_7d_range: 0.015
  };

  WEAK_BULL_THRESHOLDS = {
    price_30d_min: 0.04,
    price_30d_max: 0.12
  };

  async detect(df: any[], useAI: boolean = false, shadowPerformance: any = null, marketContext: any = null) {
    const metrics = this._calculateMetrics(df);
    let { regime, confidence, reasoning } = this._classifyRegime(metrics);
    ({ regime, confidence, reasoning } = this._applyNewsSentimentWeight(regime, confidence, reasoning, marketContext));

    let aiValidation = null;

    if (useAI && RegimeDetector.aiEnabled) {
      try {
        const apiKey = process.env.GEMINI_API_KEY;
        if (!apiKey) {
          console.warn("AI Regime Analysis skipped: GEMINI_API_KEY is not set.");
        } else {
          const { GoogleGenAI } = await import('@google/genai');
          const ai = new GoogleGenAI({ apiKey });

          // Use provided market context or default to mock
          const context = marketContext || {
            btc_dominance: "52%",
            fear_greed_index: 45,
            major_news: "Market awaiting key economic data",
            all_news: ["Market awaiting key economic data"]
          };

          const prompt = `You are analyzing trading system performance and news sentiment for regime validation.
Current regime detected by rule-based algorithm: ${regime}
Rule-based confidence: ${confidence}%

Technical Metrics: ${JSON.stringify(metrics)}
Shadow Performance (7d): ${JSON.stringify(shadowPerformance)}
Market Context (News & Global): ${JSON.stringify(context)}

Tasks:
1. Validate if regime classification is correct based on technicals AND news sentiment.
2. Analyze the sentiment of the provided news (all_news). Are they bullish, bearish, or neutral?
3. Identify if external factors (news, macro) explain recent shadow performance.
4. Recommend: [continue | reduce_risk | halt | switch]

Output JSON only:
{
  "regime_validation": "correct" | "misclassified",
  "news_sentiment": "bullish" | "bearish" | "neutral",
  "sentiment_score": number (-1.0 to 1.0),
  "performance_explanation": "string (1 sentence)",
  "external_factors": ["string"],
  "recommended_action": "continue" | "reduce_risk" | "halt" | "switch",
  "confidence": number (0-100)
}`;

          const response = await ai.models.generateContent({
            model: "gemini-3-flash-preview",
            contents: prompt,
            config: {
              responseMimeType: "application/json"
            }
          });

          if (response.text) {
            aiValidation = JSON.parse(response.text);
            reasoning = `AI Analysis: ${aiValidation.performance_explanation} Sentiment: ${aiValidation.news_sentiment} (${aiValidation.sentiment_score}). Rec: ${aiValidation.recommended_action}.`;

            // Adjust confidence based on sentiment alignment
            if (aiValidation.news_sentiment === 'bullish' && (regime === RegimeType.STRONG_BULL || regime === RegimeType.WEAK_BULL)) {
              confidence = Math.min(100, confidence + 5);
            } else if (aiValidation.news_sentiment === 'bearish' && regime === RegimeType.BEAR) {
              confidence = Math.min(100, confidence + 5);
            } else if (aiValidation.news_sentiment !== 'neutral') {
              // Dissonance between technicals and news
              confidence = Math.max(50, confidence - 10);
            }
          }
        }
      } catch (e: any) {
        if (e.message && e.message.includes("API_KEY_INVALID")) {
          console.error("AI Regime Analysis failed: Invalid API Key. Disabling AI features.");
          RegimeDetector.aiEnabled = false;
        } else {
          console.error("AI Regime Analysis failed:", e);
        }
      }
    }

    return {
      regime,
      confidence,
      metrics,
      reasoning,
      aiValidation,
      timestamp: df[df.length - 1]?.time || null
    };
  }

  _calculateMetrics(df: any[]) {
    const periods_30d = Math.min(df.length, 2880);
    const periods_7d = Math.min(df.length, 672);

    const price_30d = this._calculatePriceChange(df, periods_30d);
    const price_7d = this._calculatePriceChange(df, periods_7d);

    const lastRow = df[df.length - 1];
    const adx = lastRow.adx;

    const last30d = df.slice(-periods_30d);
    const avg_volume_30d = last30d.reduce((sum, row) => sum + (row.volume || 0), 0) / last30d.length;

    const last7d = df.slice(-periods_7d);
    const avg_volume_7d = last7d.reduce((sum, row) => sum + (row.volume || 0), 0) / last7d.length;

    const volume_ratio = avg_volume_30d > 0 ? avg_volume_7d / avg_volume_30d : 1;

    const rsi_avg_7d = last7d.reduce((sum, row) => sum + (row.rsi_14 || 0), 0) / last7d.length;

    return {
      price_change_30d: price_30d,
      price_change_7d: price_7d,
      adx,
      volume_ratio,
      rsi_avg_7d
    };
  }

  _calculatePriceChange(df: any[], periods: number) {
    if (df.length < periods) periods = df.length;
    if (periods === 0) return 0;

    const current = df[df.length - 1].close;
    const past = df[df.length - periods].close;

    return (current - past) / past;
  }

  _classifyRegime(metrics: any) {
    const { adx, price_change_30d, price_change_7d, volume_ratio, rsi_avg_7d } = metrics;

    // console.log(`[RegimeDetector] Classifying: adx=${adx}, price30d=${price_change_30d}, price7d=${price_change_7d}, vol=${volume_ratio}`);

    if (
      adx > this.STRONG_BULL_THRESHOLDS.adx_min &&
      price_change_30d > this.STRONG_BULL_THRESHOLDS.price_30d_min &&
      price_change_7d >= this.STRONG_BULL_THRESHOLDS.price_7d_min &&
      volume_ratio >= this.STRONG_BULL_THRESHOLDS.volume_ratio_min
    ) {
      return {
        regime: RegimeType.STRONG_BULL,
        confidence: 95,
        reasoning: `Strong uptrend: ADX ${adx.toFixed(1)}, +${(price_change_30d * 100).toFixed(1)}% (30d), volume ${volume_ratio.toFixed(1)}x average`
      };
    }

    if (
      price_change_30d < this.BEAR_THRESHOLDS.price_30d_max ||
      (price_change_7d < this.BEAR_THRESHOLDS.price_7d_max && rsi_avg_7d < this.BEAR_THRESHOLDS.rsi_avg_max)
    ) {
      return {
        regime: RegimeType.BEAR,
        confidence: 85,
        reasoning: `Downtrend detected: ${(price_change_30d * 100).toFixed(1)}% (30d), RSI avg ${rsi_avg_7d.toFixed(1)}`
      };
    }

    if (
      adx < this.SIDEWAYS_THRESHOLDS.adx_max &&
      Math.abs(price_change_30d) < this.SIDEWAYS_THRESHOLDS.price_30d_range &&
      Math.abs(price_change_7d) < this.SIDEWAYS_THRESHOLDS.price_7d_range
    ) {
      return {
        regime: RegimeType.SIDEWAYS,
        confidence: 80,
        reasoning: `Range-bound: ADX ${adx.toFixed(1)}, price ±${(Math.abs(price_change_30d) * 100).toFixed(1)}% (30d)`
      };
    }

    if (
      price_change_30d > this.WEAK_BULL_THRESHOLDS.price_30d_min &&
      price_change_30d < this.WEAK_BULL_THRESHOLDS.price_30d_max
    ) {
      return {
        regime: RegimeType.WEAK_BULL,
        confidence: 70,
        reasoning: `Weak uptrend: +${(price_change_30d * 100).toFixed(1)}% (30d), ADX ${adx.toFixed(1)}`
      };
    }

    return {
      regime: RegimeType.UNCERTAIN,
      confidence: 50,
      reasoning: "Market regime unclear, awaiting confirmation"
    };
  }

  _applyNewsSentimentWeight(regime: RegimeType, confidence: number, reasoning: string, marketContext: any) {
    if (!marketContext) return { regime, confidence, reasoning };

    const sentimentLabel = String(marketContext.news_sentiment || '').toLowerCase();
    const rawScore = Number(marketContext.sentiment_score ?? Number.NaN);
    const score = Number.isFinite(rawScore)
      ? Math.max(-1, Math.min(1, rawScore))
      : sentimentLabel === 'bullish'
        ? 0.5
        : sentimentLabel === 'bearish'
          ? -0.5
          : 0;
    if (score === 0) return { regime, confidence, reasoning };

    const isBullRegime = regime === RegimeType.STRONG_BULL || regime === RegimeType.WEAK_BULL;
    const aligns = (score > 0 && isBullRegime) || (score < 0 && regime === RegimeType.BEAR);
    const magnitudeBoost = Math.max(2, Math.round(Math.abs(score) * 10));

    if (aligns) {
      const boostedConfidence = Math.min(100, confidence + magnitudeBoost);
      return {
        regime,
        confidence: boostedConfidence,
        reasoning: `${reasoning}. News sentiment alignment score=${score.toFixed(2)} boosted confidence by ${boostedConfidence - confidence}.`
      };
    }

    if (regime === RegimeType.UNCERTAIN && Math.abs(score) >= 0.75) {
      const sentimentRegime = score > 0 ? RegimeType.WEAK_BULL : RegimeType.BEAR;
      const sentimentConfidence = Math.max(confidence, 60 + Math.round(Math.abs(score) * 10));
      return {
        regime: sentimentRegime,
        confidence: Math.min(85, sentimentConfidence),
        reasoning: `${reasoning}. Strong news sentiment score=${score.toFixed(2)} nudged regime to ${sentimentRegime}.`
      };
    }

    const reducedConfidence = Math.max(45, confidence - Math.max(4, magnitudeBoost));
    return {
      regime,
      confidence: reducedConfidence,
      reasoning: `${reasoning}. News sentiment dissonance score=${score.toFixed(2)} reduced confidence by ${confidence - reducedConfidence}.`
    };
  }

  shouldUpdateRegime(lastRegime: RegimeType, newRegime: RegimeType, newConfidence: number) {
    if (lastRegime !== newRegime && newConfidence > 75) return true;
    if (lastRegime === RegimeType.UNCERTAIN && newConfidence > 70) return true;
    return false;
  }
}
